import { MongoClient } from 'mongodb';
import { config } from './config.js';

// One client per process. The driver reconnects by itself if Mongo restarts;
// operations that fail while it is down throw, and the error handler turns them into 503.
const client = new MongoClient(config.mongoUrl, {
  serverSelectionTimeoutMS: 3000, // fail fast instead of hanging requests
  maxPoolSize: 20,
});

let db;

export async function connectMongo({ attempts = 30 } = {}) {
  for (let i = 1; ; i++) {
    try {
      await client.connect();
      db = client.db(); // database name comes from the URL
      await ensureIndexes();
      console.log('[mongo] connected');
      return db;
    } catch (err) {
      if (i >= attempts) throw err;
      console.warn(`[mongo] connect failed (${i}/${attempts}): ${err.message}`);
      await new Promise((r) => setTimeout(r, 1000));
    }
  }
}

export function getDb() {
  if (!db) throw new Error('Mongo not connected yet');
  return db;
}

export async function closeMongo() {
  await client.close().catch(() => {});
}

// Indexes are created at startup. createIndex is a no-op if the index already exists,
// so it is safe when several instances start at the same time.
async function ensureIndexes() {
  // Idempotency records expire after 24h
  await db.collection('idempotency').createIndex({ createdAt: 1 }, { expireAfterSeconds: 24 * 3600 });
  // TODO(on the day): add unique indexes for the real collections here
}

