import { createHash } from 'node:crypto';
import { getDb } from './db.js';
import { HttpError } from './errors.js';

const PROCESSING_LEASE_MS = 30_000; // if the handler crashes, another try can take over after this

/**
 * Express middleware: makes a POST/PUT endpoint safe to retry via the Idempotency-Key header.
 * - First request with a key: runs the handler, stores the response.
 * - Same key again after it finished: returns the stored response, handler NOT run again.
 * - Same key while the first is still running (any instance): 409.
 * - Same key but a different body: 422.
 * - If the instance died mid-request, the lease expires and a retry may run it again,
 *   so the handler itself must also be safe (unique indexes / status fields).
 *
 * Usage: app.post('/things', idempotent({ required: true }), handler)
 */
export function idempotent({ required = false } = {}) {
  return async (req, res, next) => {
    const key = req.get('Idempotency-Key');
    if (!key) {
      if (required) throw new HttpError(400, 'Idempotency-Key header is required');
      return next();
    }

    const col = getDb().collection('idempotency');
    const _id = `${req.method} ${req.baseUrl}${req.path} ${key}`;
    const fingerprint = createHash('sha256').update(JSON.stringify(req.body ?? null)).digest('hex');
    const now = new Date();

    try {
      // Unique _id: only one instance can win this insert.
      await col.insertOne({ _id, status: 'processing', fingerprint, lockedUntil: new Date(now.getTime() + PROCESSING_LEASE_MS), createdAt: now });
    } catch (err) {
      if (err.code !== 11000) throw err;
      const existing = await col.findOne({ _id });
      if (!existing) throw new HttpError(409, 'Request in progress, retry'); // expired between calls
      if (existing.fingerprint !== fingerprint) throw new HttpError(422, 'Idempotency-Key reused with a different body');
      if (existing.status === 'completed') {
        res.set('Idempotent-Replayed', 'true');
        return res.status(existing.response.status).json(existing.response.body);
      }
      // Still processing. Take over only if the lease has expired (the original holder probably died).
      const taken = await col.findOneAndUpdate(
        { _id, status: 'processing', lockedUntil: { $lt: now } },
        { $set: { lockedUntil: new Date(now.getTime() + PROCESSING_LEASE_MS) } },
      );
      if (!taken) {
        res.set('Retry-After', '1');
        throw new HttpError(409, 'Request with this Idempotency-Key is already in progress');
      }
    }

    // Capture the response: store it BEFORE sending, so a retry never sees a missing result.
    const sendJson = res.json.bind(res);
    res.json = (body) => {
      const status = res.statusCode;
      const save =
        status >= 500
          ? col.deleteOne({ _id }) // server error: allow a clean retry
          : col.updateOne({ _id }, { $set: { status: 'completed', response: { status, body } } });
      save.catch((e) => console.error('[idempotency] save failed', e.message)).finally(() => sendJson(body));
      return res;
    };
    next();
  };
}

