// Small fetch helper for the frontend.
// For writes, pass an idempotency key created ONCE per user action (e.g. per form submit),
// so a double click or a retry doesn't create the thing twice.

export class ApiError extends Error {
  constructor(status, message, body) {
    super(message);
    this.status = status;
    this.body = body;
  }
}

export const newKey = () => crypto.randomUUID();

export async function api(path, { method = 'GET', body, idempotencyKey, timeoutMs = 10000 } = {}) {
  const res = await fetch(`/api${path}`, {
    method,
    headers: {
      ...(body !== undefined && { 'content-type': 'application/json' }),
      ...(idempotencyKey && { 'Idempotency-Key': idempotencyKey }),
      ...(localStorage.token && { authorization: `Bearer ${localStorage.token}` }),
    },
    body: body !== undefined ? JSON.stringify(body) : undefined,
    signal: AbortSignal.timeout(timeoutMs),
  });
  const text = await res.text();
  let data = null;
  try {
    data = text ? JSON.parse(text) : null;
  } catch {
    data = text;
  }
  if (!res.ok) throw new ApiError(res.status, data?.error || `Request failed (${res.status})`, data);
  return data;
}

