{
  "name": "server",
  "private": true,
  "type": "module",
  "engines": { "node": ">=22" },
  "scripts": {
    "start": "node src/index.js",
    "dev": "node --watch src/index.js"
  },
  "dependencies": {
    "express": "^5.1.0",
    "ioredis": "^5.4.1",
    "mongodb": "^6.10.0"
  }
}

// All configuration comes from environment variables, with defaults for local runs.
export const config = {
  port: Number(process.env.PORT || 4000),
  mongoUrl: process.env.MONGO_URL || 'mongodb://localhost:27017/app',
  redisUrl: process.env.REDIS_URL || 'redis://localhost:6379',
  // Provided services (fill in / confirm from the packet)
  pigeonUrl: process.env.PIGEON_URL || 'http://localhost:4010',
  idpUrl: process.env.IDP_URL || 'http://localhost:4020',
  payboxUrl: process.env.PAYBOX_URL || 'http://localhost:4030',
  // Unique per process: useful in logs when several copies run at once
  instanceId: process.env.INSTANCE_ID || `${process.pid}`,
};

import { MongoClient } from 'mongodb';
import { config } from './config.js';

// One client per process. The driver reconnects by itself if Mongo restarts;
// operations that fail while it is down throw, and the error handler turns them into 503.
const client = new MongoClient(config.mongoUrl, {
  serverSelectionTimeoutMS: 3000, // fail fast instead of hanging requests
  maxPoolSize: 20,
});

let db;

export async function connectMongo({ attempts = 30 } = {}) {
  for (let i = 1; ; i++) {
    try {
      await client.connect();
      db = client.db(); // database name comes from the URL
      await ensureIndexes();
      console.log('[mongo] connected');
      return db;
    } catch (err) {
      if (i >= attempts) throw err;
      console.warn(`[mongo] connect failed (${i}/${attempts}): ${err.message}`);
      await new Promise((r) => setTimeout(r, 1000));
    }
  }
}

export function getDb() {
  if (!db) throw new Error('Mongo not connected yet');
  return db;
}

export async function closeMongo() {
  await client.close().catch(() => {});
}

// Indexes are created at startup. createIndex is a no-op if the index already exists,
// so it is safe when several instances start at the same time.
async function ensureIndexes() {
  // Idempotency records expire after 24h
  await db.collection('idempotency').createIndex({ createdAt: 1 }, { expireAfterSeconds: 24 * 3600 });
  // TODO(on the day): add unique indexes for the real collections here
}

import Redis from 'ioredis';
import { randomUUID } from 'node:crypto';
import { config } from './config.js';

// enableOfflineQueue=false: if Redis is down, commands fail immediately (-> 503)
// instead of queueing forever and making requests hang.
export const redis = new Redis(config.redisUrl, {
  lazyConnect: true,
  enableOfflineQueue: false,
  maxRetriesPerRequest: 1,
  retryStrategy: (times) => Math.min(times * 200, 2000), // keep reconnecting
});

redis.on('error', (err) => console.warn('[redis]', err.message));

export async function connectRedis() {
  await redis.connect();
  console.log('[redis] connected');
}

export async function closeRedis() {
  await redis.quit().catch(() => redis.disconnect());
}

// Delete the key only if we still own it (compare token), so we never release
// a lock that expired and was taken by another instance.
const RELEASE = `if redis.call("get", KEYS[1]) == ARGV[1] then return redis.call("del", KEYS[1]) else return 0 end`;

/**
 * Run fn while holding a distributed lock. Returns { acquired: false } if someone else holds it.
 * ttlMs must be longer than fn normally takes; the TTL means a crashed holder can't block forever.
 */
export async function withLock(key, ttlMs, fn) {
  const token = randomUUID();
  const ok = await redis.set(key, token, 'PX', ttlMs, 'NX');
  if (!ok) return { acquired: false };
  try {
    return { acquired: true, value: await fn() };
  } finally {
    await redis.eval(RELEASE, 1, key, token).catch(() => {});
  }
}

// Calls to the provided services (Pigeon, Paybox, IdP): timeout + retry with backoff.

export class UpstreamError extends Error {
  constructor(message, { status, data } = {}) {
    super(message);
    this.status = status;
    this.data = data;
  }
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// Exponential backoff with jitter: ~200ms, 400ms, 800ms... capped at 3s
function backoffMs(attempt, retryAfterHeader) {
  const ra = Number(retryAfterHeader);
  if (ra > 0) return Math.min(ra * 1000, 5000);
  const base = Math.min(200 * 2 ** attempt, 3000);
  return base / 2 + Math.random() * (base / 2);
}

/**
 * callService(url, { method, body, headers, timeoutMs, retries, idempotencyKey })
 * Returns { status, ok, data }. Throws UpstreamError if all attempts fail on network/timeout.
 *
 * IMPORTANT: a non-GET call is only retried when an idempotencyKey is given; otherwise a
 * retry after a timeout could do the action twice (e.g. charge twice).
 * A timeout means "outcome unknown", not "failed": the caller must handle that.
 */
export async function callService(url, opts = {}) {
  const { method = 'GET', body, headers = {}, timeoutMs = 3000, retries = 3, idempotencyKey } = opts;
  const safeToRetry = method === 'GET' || method === 'HEAD' || !!idempotencyKey;
  const maxRetries = safeToRetry ? retries : 0;

  for (let attempt = 0; ; attempt++) {
    try {
      const res = await fetch(url, {
        method,
        headers: {
          ...(body !== undefined && { 'content-type': 'application/json' }),
          ...(idempotencyKey && { 'Idempotency-Key': idempotencyKey }),
          ...headers,
        },
        body: body !== undefined ? JSON.stringify(body) : undefined,
        signal: AbortSignal.timeout(timeoutMs),
      });

      if ((res.status >= 500 || res.status === 429) && attempt < maxRetries) {
        await sleep(backoffMs(attempt, res.headers.get('retry-after')));
        continue;
      }

      const text = await res.text();
      let data;
      try {
        data = text ? JSON.parse(text) : null;
      } catch {
        data = text;
      }
      return { status: res.status, ok: res.ok, data };
    } catch (err) {
      // network error or timeout
      if (attempt >= maxRetries) {
        throw new UpstreamError(`${method} ${url} failed after ${attempt + 1} attempt(s): ${err.name === 'TimeoutError' ? 'timeout' : err.message}`);
      }
      await sleep(backoffMs(attempt));
    }
  }
}

import { createHash } from 'node:crypto';
import { getDb } from './db.js';
import { HttpError } from './errors.js';

const PROCESSING_LEASE_MS = 30_000; // if the handler crashes, another try can take over after this

/**
 * Express middleware: makes a POST/PUT endpoint safe to retry via the Idempotency-Key header.
 * - First request with a key: runs the handler, stores the response.
 * - Same key again after it finished: returns the stored response, handler NOT run again.
 * - Same key while the first is still running (any instance): 409.
 * - Same key but a different body: 422.
 * - If the instance died mid-request, the lease expires and a retry may run it again,
 *   so the handler itself must also be safe (unique indexes / status fields).
 *
 * Usage: app.post('/things', idempotent({ required: true }), handler)
 */
export function idempotent({ required = false } = {}) {
  return async (req, res, next) => {
    const key = req.get('Idempotency-Key');
    if (!key) {
      if (required) throw new HttpError(400, 'Idempotency-Key header is required');
      return next();
    }

    const col = getDb().collection('idempotency');
    const _id = `${req.method} ${req.baseUrl}${req.path} ${key}`;
    const fingerprint = createHash('sha256').update(JSON.stringify(req.body ?? null)).digest('hex');
    const now = new Date();

    try {
      // Unique _id: only one instance can win this insert.
      await col.insertOne({ _id, status: 'processing', fingerprint, lockedUntil: new Date(now.getTime() + PROCESSING_LEASE_MS), createdAt: now });
    } catch (err) {
      if (err.code !== 11000) throw err;
      const existing = await col.findOne({ _id });
      if (!existing) throw new HttpError(409, 'Request in progress, retry'); // expired between calls
      if (existing.fingerprint !== fingerprint) throw new HttpError(422, 'Idempotency-Key reused with a different body');
      if (existing.status === 'completed') {
        res.set('Idempotent-Replayed', 'true');
        return res.status(existing.response.status).json(existing.response.body);
      }
      // Still processing. Take over only if the lease has expired (the original holder probably died).
      const taken = await col.findOneAndUpdate(
        { _id, status: 'processing', lockedUntil: { $lt: now } },
        { $set: { lockedUntil: new Date(now.getTime() + PROCESSING_LEASE_MS) } },
      );
      if (!taken) {
        res.set('Retry-After', '1');
        throw new HttpError(409, 'Request with this Idempotency-Key is already in progress');
      }
    }

    // Capture the response: store it BEFORE sending, so a retry never sees a missing result.
    const sendJson = res.json.bind(res);
    res.json = (body) => {
      const status = res.statusCode;
      const save =
        status >= 500
          ? col.deleteOne({ _id }) // server error: allow a clean retry
          : col.updateOne({ _id }, { $set: { status: 'completed', response: { status, body } } });
      save.catch((e) => console.error('[idempotency] save failed', e.message)).finally(() => sendJson(body));
      return res;
    };
    next();
  };
}

import { UpstreamError } from './http.js';

export class HttpError extends Error {
  constructor(status, message, details) {
    super(message);
    this.status = status;
    this.details = details;
  }
}

// Express 5 forwards rejected promises from async handlers here automatically.
// eslint-disable-next-line no-unused-vars
export function errorHandler(err, req, res, next) {
  let status = 500;
  let message = 'Internal error';

  if (err instanceof HttpError) {
    status = err.status;
    message = err.message;
  } else if (err.type === 'entity.parse.failed') {
    status = 400;
    message = 'Invalid JSON body';
  } else if (err.code === 11000) {
    status = 409;
    message = 'Duplicate';
  } else if (err instanceof UpstreamError) {
    status = 502;
    message = err.message;
  } else if (isDependencyDown(err)) {
    status = 503;
    message = 'A dependency is unavailable, retry later';
    res.set('Retry-After', '1');
  }

  if (status >= 500) console.error(`[error] ${req.method} ${req.originalUrl}`, err);
  if (res.headersSent) return;
  res.status(status).json({ error: message, ...(err.details && { details: err.details }) });
}

function isDependencyDown(err) {
  const name = err?.name || '';
  const msg = err?.message || '';
  return (
    name.startsWith('MongoServerSelection') ||
    name.startsWith('MongoNetwork') ||
    name === 'MongoNotConnectedError' ||
    msg.includes("Stream isn't writeable") || // ioredis with offline queue disabled
    msg.includes('Connection is closed') ||
    msg.includes('ECONNREFUSED')
  );
}

import express from 'express';
import { getDb } from './db.js';
import { redis } from './redis.js';
import { config } from './config.js';
import { errorHandler, HttpError } from './errors.js';

export function createApp() {
  const app = express();
  app.disable('x-powered-by');
  app.use(express.json({ limit: '1mb' }));

  // Liveness: the process is up.
  app.get('/healthz', (req, res) => res.json({ ok: true, instance: config.instanceId }));

  // Readiness: dependencies reachable.
  app.get('/readyz', async (req, res) => {
    const [mongo, red] = await Promise.all([
      getDb().command({ ping: 1 }).then(() => true, () => false),
      redis.ping().then(() => true, () => false),
    ]);
    res.status(mongo && red ? 200 : 503).json({ ok: mongo && red, mongo, redis: red });
  });

  // TODO(on the day): mount feature routes here, e.g. app.use('/things', thingsRouter);

  app.use((req, res) => {
    throw new HttpError(404, 'Not found');
  });
  app.use(errorHandler);
  return app;
}

import { config } from './config.js';
import { connectMongo, closeMongo } from './db.js';
import { connectRedis, closeRedis } from './redis.js';
import { createApp } from './app.js';

async function main() {
  await Promise.all([connectMongo(), connectRedis()]);

  const server = createApp().listen(config.port, () => console.log(`[server] instance ${config.instanceId} listening on :${config.port}`));
  server.requestTimeout = 30_000; // never let a request hang forever
  server.keepAliveTimeout = 5_000;

  // TODO(on the day): start background workers here (e.g. resume 'pending' jobs left by a crash)

  let shuttingDown = false;
  async function shutdown(signal) {
    if (shuttingDown) return;
    shuttingDown = true;
    console.log(`[server] ${signal}: shutting down`);
    const force = setTimeout(() => {
      console.warn('[server] forcing exit');
      process.exit(1);
    }, 10_000);
    force.unref();

    // Stop accepting new connections and wait for in-flight requests to finish.
    server.closeIdleConnections();
    await new Promise((r) => server.close(r));
    await Promise.all([closeMongo(), closeRedis()]);
    console.log('[server] bye');
    process.exit(0);
  }
  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT', () => shutdown('SIGINT'));
}

process.on('unhandledRejection', (err) => console.error('[unhandledRejection]', err));

main().catch((err) => {
  console.error('[server] failed to start', err);
  process.exit(1);
});

