import type { Request, Response, NextFunction, RequestHandler } from 'express';

// Throw this from any handler to answer with a specific status.
export class HttpError extends Error {
  constructor(public status: number, message: string) {
    super(message);
  }
}

// Express 4 does not catch errors from async handlers: the request would hang.
// Wrap every async handler: router.post('/x', ah(async (req, res) => { ... }))
export const ah =
  (fn: (req: Request, res: Response, next: NextFunction) => Promise<unknown>): RequestHandler =>
  (req, res, next) => {
    fn(req, res, next).catch(next);
  };

// Last middleware: turns any error into a JSON answer. Never leaves a request hanging.
export function errorHandler(err: any, req: Request, res: Response, _next: NextFunction): void {
  let status = 500;
  let message = 'Internal error';

  if (err instanceof HttpError) {
    status = err.status;
    message = err.message;
  } else if (err?.type === 'entity.parse.failed') {
    status = 400;
    message = 'Invalid JSON body';
  } else if (err?.code === 11000) {
    status = 409;
    message = 'Duplicate';
  } else if (isDependencyDown(err)) {
    status = 503;
    message = 'A dependency is unavailable, retry later';
    res.set('Retry-After', '1');
  }

  if (status >= 500) console.error(`[error] ${req.method} ${req.originalUrl}`, err);
  if (res.headersSent) return;
  res.status(status).json({ error: message });
}

function isDependencyDown(err: any): boolean {
  const name: string = err?.name ?? '';
  const msg: string = err?.message ?? '';
  return (
    name.startsWith('MongoServerSelection') ||
    name.startsWith('MongoNetwork') ||
    name === 'MongoNotConnectedError' ||
    name === 'MaxRetriesPerRequestError' ||
    msg.includes('ECONNREFUSED') ||
    msg.includes('Connection is closed')
  );
}

import express from 'express';
import { errorHandler, HttpError } from './http.js';

// Set to true when SIGTERM arrives, so the load balancer stops sending us traffic.
export const state = { shuttingDown: false };

export function createApp() {
  const app = express();
  app.disable('x-powered-by');

  // Health: 200 once the server is ready (we only start listening after Mongo and Redis connect),
  // 503 while shutting down.
  app.get('/healthz', (_req, res) => {
    if (state.shuttingDown) return res.status(503).json({ ok: false });
    res.json({ ok: true });
  });

  // NOTE: the Pigeon webhook router goes HERE, before express.json(),
  // because the signature is computed over the raw body (task 2).

  app.use(express.json({ limit: '1mb' }));

  // Routes are added here as we build them (grader, api, auth).

  app.use((_req, _res, next) => next(new HttpError(404, 'Not found')));
  app.use(errorHandler);
  return app;
}

import { createServer } from 'node:http';
import { config } from './config.js';
import { connectDb, closeDb } from './db.js';
import { connectRedis, closeRedis } from './redis.js';
import { createApp, state } from './app.js';

async function main() {
  // Connect first, then listen: /healthz only answers once we can serve traffic.
  await Promise.all([connectDb(), connectRedis()]);

  // A plain http server, so we can attach WebSockets to it later (task 5).
  const server = createServer(createApp());
  server.requestTimeout = 30_000; // never let a request hang forever
  server.keepAliveTimeout = 5_000;

  server.listen(config.port, () => {
    console.log(`[server] pid ${process.pid} listening on http://localhost:${config.port}`);
  });

  // Background workers start here later (sender worker, task 4).

  async function shutdown(signal: string) {
    if (state.shuttingDown) return;
    state.shuttingDown = true;
    console.log(`[server] ${signal}: shutting down`);

    const force = setTimeout(() => {
      console.warn('[server] forcing exit');
      process.exit(1);
    }, config.shutdownTimeoutMs);
    force.unref();

    // Stop accepting connections, let in-flight requests finish, then close stores.
    server.closeIdleConnections();
    await new Promise<void>((resolve) => server.close(() => resolve()));
    await Promise.all([closeDb(), closeRedis()]);
    console.log('[server] bye');
    process.exit(0);
  }
  process.on('SIGTERM', () => void shutdown('SIGTERM'));
  process.on('SIGINT', () => void shutdown('SIGINT'));
}

process.on('unhandledRejection', (err) => console.error('[unhandledRejection]', err));

main().catch((err) => {
  console.error('[server] failed to start', err);
  process.exit(1);
});

