    d.collection(C.messages).createIndex({ status: 1, nextAttemptAt: 1 }),

    // Real-time events: seq is unique within a workspace, replay with seq > after.
    d.collection(C.events).createIndex({ workspace: 1, seq: 1 }, { unique: true }),
