import express, { Router } from 'express';
import { createHmac, timingSafeEqual } from 'node:crypto';
import { config, isKnownWorkspace } from './config.js';
import { db, C } from './db.js';
import { ah } from './http.js';
import { emitEvent } from './events.js';

const MAX_AGE_SECONDS = 5 * 60;

// Status only moves forward. delivered/failed are final, so a late "sent" can't overwrite them.
export const STATUS_RANK: Record<string, number> = { queued: 0, sent: 1, delivered: 2, failed: 2 };

export const webhookRouter = Router();

// Raw body (Buffer): the signature is computed over the exact bytes Pigeon sent.
webhookRouter.post(
  '/pigeon',
  express.raw({ type: '*/*', limit: '1mb' }),
  ah(async (req, res) => {
    const raw: Buffer = Buffer.isBuffer(req.body) ? req.body : Buffer.alloc(0);

    // 2.1 Authenticity first. Anything wrong here is 401, never 5xx, and nothing is stored.
    const sig = verifySignature(req.get('x-pigeon-signature'), raw);
    if (sig !== 'ok') return res.status(401).json({ error: sig });

    // 2.2 Genuine but unparseable -> 400.
    let event: any;
    try {
      event = JSON.parse(raw.toString('utf8'));
    } catch {
      return res.status(400).json({ error: 'Body is not valid JSON' });
    }
    if (!event || typeof event !== 'object' || typeof event.type !== 'string') {
      return res.status(400).json({ error: 'Missing event type' });
    }

    // Unknown workspace or unknown type: acknowledge and ignore, or Pigeon keeps retrying.
    if (!isKnownWorkspace(event.workspace)) return res.json({ ok: true, ignored: 'unknown workspace' });

    if (event.type === 'message.inbound') {
      const d = event.data;
      if (!d || typeof d.message_id !== 'string' || typeof d.from !== 'string') {
        return res.status(400).json({ error: 'Bad message.inbound data' });
      }
      await storeInbound(event.workspace, d.message_id, d.from, String(d.text ?? ''), event.occurred_at);
      return res.json({ ok: true }); // 2.5 only after it is stored
    }

    if (event.type === 'message.status') {
      const d = event.data;
      if (!d || typeof d.client_ref !== 'string' || typeof d.status !== 'string') {
        return res.status(400).json({ error: 'Bad message.status data' });
      }
      await applyStatus(event.workspace, d.client_ref, d.status, d.message_id);
      return res.json({ ok: true });
    }

    return res.json({ ok: true, ignored: 'unknown event type' });
  }),
);

// Header: "t=<unix seconds>,v1=<hex>", v1 = HMAC-SHA256("<t>.<raw body>", secret)
function verifySignature(header: string | undefined, raw: Buffer): 'ok' | string {
  if (!header) return 'Missing signature';
  const parts = Object.fromEntries(
    header.split(',').map((p) => {
      const i = p.indexOf('=');
      return [p.slice(0, i).trim(), p.slice(i + 1).trim()];
    }),
  );
  const t = Number(parts.t);
  const v1 = parts.v1;
  if (!Number.isInteger(t) || !v1 || !/^[0-9a-f]+$/i.test(v1)) return 'Malformed signature';

  const expected = createHmac('sha256', config.pigeon.webhookSecret).update(`${t}.`).update(raw).digest();
  const given = Buffer.from(v1, 'hex');
  if (given.length !== expected.length || !timingSafeEqual(given, expected)) return 'Bad signature';

  // Checked after the HMAC, so the timestamp itself can't be forged.
  const age = Math.floor(Date.now() / 1000) - t;
  if (age > MAX_AGE_SECONDS || age < -MAX_AGE_SECONDS) return 'Stale timestamp';
  return 'ok';
}

// 2.3 Store a customer message exactly once, then update its conversation.
async function storeInbound(workspace: string, messageId: string, from: string, text: string, occurredAtRaw: unknown) {
  const occurredAt = parseDate(occurredAtRaw);
  const messages = db().collection(C.messages);

  // Upsert on the unique key: a duplicate (even at the same instant) never creates a second row.
  const doc = await retryOnDuplicate(() =>
    messages.findOneAndUpdate(
      { workspace, direction: 'in', providerMessageId: messageId },
      { $setOnInsert: { contact: from, text, occurredAt, receivedAt: new Date(), evented: false } },
      { upsert: true, returnDocument: 'after' },
    ),
  );

  await touchConversation(workspace, from, occurredAt);

  // Emit the realtime event once. If we crashed after storing but before emitting,
  // Pigeon's retry lands here with evented=false and the event goes out then.
  if (doc && !doc.evented) {
    await emitEvent(workspace, 'message.inbound', { contact: from, message_id: messageId, text, occurred_at: occurredAt });
    await messages.updateOne({ _id: doc._id }, { $set: { evented: true } });
  }
}

// One conversation per contact; lastActivityAt only moves forward.
export async function touchConversation(workspace: string, contact: string, at: Date) {
  await retryOnDuplicate(() =>
    db()
      .collection(C.conversations)
      .updateOne(
        { workspace, contact },
        { $setOnInsert: { assignee: null, state: 'open', createdAt: new Date() }, $max: { lastActivityAt: at } },
        { upsert: true },
      ),
  );
}

// 2.4 Status of a reply we sent. Unknown client_ref -> ignored (no upsert).
async function applyStatus(workspace: string, clientRef: string, status: string, providerMessageId: unknown) {
  const rank = STATUS_RANK[status];
  if (rank === undefined) return; // a status we don't know: ignore

  const updated = await db()
    .collection(C.messages)
    .findOneAndUpdate(
      { workspace, direction: 'out', clientRef, statusRank: { $lt: rank } },
      {
        $set: {
          status,
          statusRank: rank,
          statusAt: new Date(),
          ...(typeof providerMessageId === 'string' && { providerMessageId }),
        },
      },
      { returnDocument: 'after' },
    );
  // Nothing updated = unknown client_ref, duplicate, or an older status arriving late.
  if (updated) {
    await emitEvent(workspace, 'message.status', { contact: updated.contact, client_ref: clientRef, status });
  }
}

// Two concurrent upserts on the same unique key: one inserts, the other gets E11000.
// Running it again turns the loser into a plain update.
async function retryOnDuplicate<T>(fn: () => Promise<T>): Promise<T> {
  try {
    return await fn();
  } catch (err: any) {
    if (err?.code === 11000) return fn();
    throw err;
  }
}

function parseDate(v: unknown): Date {
  const d = typeof v === 'string' ? new Date(v) : new Date(NaN);
  return Number.isNaN(d.getTime()) ? new Date() : d;
}

