    let cursor = '0';
    do {
      const [next, keys] = await redis.scan(cursor, 'MATCH', 'sb:*', 'COUNT', 500);
      cursor = next;
      const toDelete = keys.filter((k) => !k.startsWith('sb:sess:'));
