import { config } from '../config.js';

// HTTP client for Pigeon's send API. Turns every possible answer into one of four outcomes.
export type SendOutcome =
  | { kind: 'accepted'; providerMessageId?: string }
  | { kind: 'rate_limited'; retryAfterMs: number } // 429
  | { kind: 'retry'; reason: string } // 5xx, timeout, network: try again later
  | { kind: 'rejected'; status: number; reason: string }; // other 4xx: will never succeed

const TIMEOUT_MS = 4000; // Pigeon sometimes answers after 12 s; we retry with the same Idempotency-Key

export async function sendMessage(workspace: string, to: string, text: string, clientRef: string): Promise<SendOutcome> {
  const apiKey = config.pigeon.apiKeys[workspace];
  if (!apiKey) return { kind: 'rejected', status: 0, reason: 'no API key for workspace' };

  let res: Response;
  try {
    res = await fetch(`${config.pigeon.url}/v1/messages`, {
      method: 'POST',
      headers: {
        authorization: `Bearer ${apiKey}`,
        'content-type': 'application/json',
        // Same key on every retry: Pigeon returns the original result and does not send again.
        'idempotency-key': clientRef,
      },
      body: JSON.stringify({ to, text, client_ref: clientRef }),
      signal: AbortSignal.timeout(TIMEOUT_MS),
    });
  } catch (err: any) {
    return { kind: 'retry', reason: err?.name === 'TimeoutError' ? 'timeout' : `network: ${err?.message}` };
  }

  if (res.ok) {
    const body: any = await res.json().catch(() => ({}));
    return { kind: 'accepted', providerMessageId: typeof body?.id === 'string' ? body.id : undefined };
  }
  await res.body?.cancel().catch(() => {});

  if (res.status === 429) {
    const seconds = Number(res.headers.get('retry-after'));
    return { kind: 'rate_limited', retryAfterMs: (Number.isFinite(seconds) && seconds > 0 ? seconds : 1) * 1000 };
  }
  if (res.status >= 500 || res.status === 408) return { kind: 'retry', reason: `HTTP ${res.status}` };
  return { kind: 'rejected', status: res.status, reason: `HTTP ${res.status}` };
}

import { getRedis } from './redis.js';

// Pigeon allows a bucket of 8 sends per workspace, refilling at 4/s. We stay a little under it,
// so normally we never get a 429. The bucket lives in Redis, so all server copies share it.
const CAPACITY = 6;
const REFILL_PER_SEC = 3.5;

// Atomic in Redis (a Lua script runs without interruption). Uses Redis' own clock, so copies
// with slightly different clocks still agree.
// Returns 0 = go ahead (a token was taken), otherwise how many ms to wait.
const TAKE = `
local now_parts = redis.call('TIME')
local now = tonumber(now_parts[1]) * 1000 + math.floor(tonumber(now_parts[2]) / 1000)

local cool = tonumber(redis.call('GET', KEYS[2]) or '0')
if cool > now then return cool - now end

local cap = tonumber(ARGV[1])
local rate = tonumber(ARGV[2])
local b = redis.call('HMGET', KEYS[1], 'tokens', 'ts')
local tokens = tonumber(b[1]) or cap
local ts = tonumber(b[2]) or now
tokens = math.min(cap, tokens + (now - ts) / 1000 * rate)

local wait = 0
if tokens >= 1 then tokens = tokens - 1 else wait = math.ceil((1 - tokens) / rate * 1000) end
redis.call('HSET', KEYS[1], 'tokens', tostring(tokens), 'ts', now)
redis.call('PEXPIRE', KEYS[1], 60000)
return wait
`;

const bucketKey = (ws: string) => `sb:rl:${ws}`;
const coolOffKey = (ws: string) => `sb:cooloff:${ws}`;

export async function takeSendToken(workspace: string): Promise<number> {
  const wait = await getRedis().eval(TAKE, 2, bucketKey(workspace), coolOffKey(workspace), CAPACITY, REFILL_PER_SEC);
  return Number(wait);
}

// After a 429: nobody in this workspace sends until Retry-After has passed (all copies).
// Stored as an absolute time (Redis clock) so the TAKE script can compare it.
const SET_COOLOFF = `
local t = redis.call('TIME')
local now = tonumber(t[1]) * 1000 + math.floor(tonumber(t[2]) / 1000)
local untilMs = now + tonumber(ARGV[1])
local cur = tonumber(redis.call('GET', KEYS[1]) or '0')
if untilMs > cur then redis.call('SET', KEYS[1], untilMs, 'PX', tonumber(ARGV[1]) + 1000) end
return untilMs
`;

export async function startCoolOff(workspace: string, ms: number): Promise<void> {
  // +250 ms margin so we are safely past Pigeon's window
  await getRedis().eval(SET_COOLOFF, 1, coolOffKey(workspace), Math.ceil(ms + 250));
}

import { db, C, retryOnDuplicate } from '../lib/db.js';
import { emitEvent } from './events.js';
import { touchConversation } from './conversations.js';
import { kickSender } from '../workers/sender.js';

/**
 * Accept a reply. Once this returns, the reply is safely stored and WILL be sent
 * (by the sender worker of any server copy), even if this process dies right now.
 *
 * Idempotent on (workspace, client_ref): asking twice, even at the same instant,
 * stores one reply. Both callers get the same answer.
 */
export async function queueReply(workspace: string, contact: string, text: string, clientRef: string, author: string | null) {
  const now = new Date();
  const r = await retryOnDuplicate(() =>
    db()
      .collection(C.messages)
      .updateOne(
        { workspace, direction: 'out', clientRef },
        {
          $setOnInsert: {
            contact,
            text,
            author,
            occurredAt: now,
            // What the agent sees: queued -> sent -> delivered | failed (from Pigeon's webhooks)
            status: 'queued',
            statusRank: 0,
            // Internal send state: pending -> sending (leased) -> accepted | rejected
            sendState: 'pending',
            nextAttemptAt: now,
            attempts: 0,
          },
        },
        { upsert: true },
      ),
  );

  // The conversation exists even if the contact never wrote (brief: grader reply).
  await touchConversation(workspace, contact, now);

  if (r.upsertedCount === 1) {
    await emitEvent(workspace, 'message.outbound', { contact, client_ref: clientRef, text, status: 'queued', author });
    kickSender(); // send now instead of waiting for the next poll
  }
}

import { randomUUID } from 'node:crypto';
import { db, C } from '../lib/db.js';
import { sendMessage } from '../lib/pigeon.js';
import { takeSendToken, startCoolOff } from '../lib/rateLimit.js';
import { emitEvent } from '../services/events.js';

/**
 * Sends queued replies to Pigeon. Runs in EVERY server copy; they coordinate through Mongo.
 *
 * Taking a job is one atomic update: sendState -> 'sending' and nextAttemptAt -> now + LEASE.
 * If this copy dies mid-send, the lease runs out, the job is "due" again, and any copy
 * takes it over (well within the 60 s the brief allows). The resend uses the same
 * Idempotency-Key, so Pigeon never delivers it twice.
 */
const LEASE_MS = 15_000; // > Pigeon timeout (4 s) + margin
const IDLE_POLL_MS = 300;
const LOOPS = 4; // parallel sends per copy (the shared rate limit caps the total)

const owner = `${process.pid}-${randomUUID().slice(0, 8)}`;
let running = false;
let wake: (() => void) | null = null;

export function kickSender() {
  wake?.();
}

export function startSender() {
  running = true;
  const loops = Array.from({ length: LOOPS }, () => loop());
  return async function stop() {
    running = false;
    kickSender();
    await Promise.all(loops);
  };
}

async function loop() {
  while (running) {
    try {
      const worked = await runOnce();
      if (!worked) await idle();
    } catch (err: any) {
      console.warn('[sender]', err?.message ?? err);
      await idle(1000);
    }
  }
}

function idle(ms = IDLE_POLL_MS) {
  return new Promise<void>((resolve) => {
    const t = setTimeout(done, ms);
    function done() {
      clearTimeout(t);
      if (wake === done) wake = null;
      resolve();
    }
    wake = done;
  });
}

const backoffMs = (attempts: number) => Math.min(500 * 2 ** attempts, 5000) * (0.75 + Math.random() * 0.5);

// Returns true if it did something (so the loop goes again immediately).
async function runOnce(): Promise<boolean> {
  const messages = db().collection(C.messages);
  const now = new Date();

  // 1. Lease one due job: pending and due, or 'sending' whose lease expired (its copy died).
  const job = await messages.findOneAndUpdate(
    { direction: 'out', sendState: { $in: ['pending', 'sending'] }, nextAttemptAt: { $lte: now } },
    { $set: { sendState: 'sending', nextAttemptAt: new Date(now.getTime() + LEASE_MS), leaseOwner: owner } },
    { sort: { nextAttemptAt: 1 }, returnDocument: 'after' },
  );
  if (!job) return false;

  // Only update the job while we still hold the lease.
  const mine = { _id: job._id, leaseOwner: owner, sendState: 'sending' };
  const later = (ms: number, extra: Record<string, unknown> = {}) =>
    messages.updateOne(mine, { $set: { sendState: 'pending', nextAttemptAt: new Date(Date.now() + ms), ...extra } });

  // 2. Shared per-workspace rate limit (and any Retry-After cool-off). Not our turn -> put it back.
  const wait = await takeSendToken(job.workspace);
  if (wait > 0) {
    await later(wait);
    return true;
  }

  // 3. Send. Same client_ref as Idempotency-Key on every attempt.
  const out = await sendMessage(job.workspace, job.contact, job.text, job.clientRef);

  switch (out.kind) {
    case 'accepted':
      // The visible status stays 'queued' until Pigeon's webhook says sent/delivered/failed.
      await messages.updateOne(mine, {
        $set: { sendState: 'accepted', acceptedAt: new Date(), ...(out.providerMessageId && { pigeonId: out.providerMessageId }) },
        $unset: { nextAttemptAt: '' },
      });
      break;

    case 'rate_limited':
      await startCoolOff(job.workspace, out.retryAfterMs); // every copy now waits
      await later(out.retryAfterMs + 250);
      break;

    case 'retry': // 503, timeout, outage: never give up, back off
      await later(backoffMs(job.attempts ?? 0), { attempts: (job.attempts ?? 0) + 1, lastError: out.reason });
      break;

    case 'rejected': {
      // Pigeon will never accept it (e.g. 400). Tell the agent it failed.
      const r = await messages.updateOne(
        { ...mine, statusRank: { $lt: 2 } },
        { $set: { sendState: 'rejected', status: 'failed', statusRank: 2, lastError: out.reason }, $unset: { nextAttemptAt: '' } },
      );
      if (r.modifiedCount) await emitEvent(job.workspace, 'message.status', { contact: job.contact, client_ref: job.clientRef, status: 'failed' });
      break;
    }
  }
  return true;
}

