* { box-sizing: border-box; }
body { margin: 0; font: 14px/1.4 system-ui, sans-serif; color: #1d1d1f; background: #f5f5f7; }
button { font: inherit; padding: 6px 12px; border: 1px solid #c7c7cc; border-radius: 6px; background: #fff; cursor: pointer; }
button:hover { background: #f0f0f2; }
button:disabled { opacity: 0.5; cursor: default; }
button.primary, a.button.primary { background: #0a66c2; border-color: #0a66c2; color: #fff; }
button.link { border: 0; padding: 0; background: none; color: #0a66c2; text-decoration: underline; }
a.button { display: inline-block; padding: 8px 18px; border-radius: 6px; text-decoration: none; }
select, input { font: inherit; padding: 6px 8px; border: 1px solid #c7c7cc; border-radius: 6px; background: #fff; }

.muted { color: #6e6e73; }
.small { font-size: 12px; }
.pad { padding: 16px; }
.error { color: #c62828; }
.spacer { flex: 1; }

.centered { max-width: 420px; margin: 15vh auto; text-align: center; }

.app { display: grid; grid-template-columns: 300px 1fr; grid-template-rows: auto 1fr; height: 100vh; }
header { grid-column: 1 / 3; display: flex; align-items: center; gap: 10px; padding: 10px 16px; background: #fff; border-bottom: 1px solid #e5e5ea; }
.dot { width: 8px; height: 8px; border-radius: 50%; background: #c7c7cc; }
.dot.on { background: #34c759; }

aside { background: #fff; border-right: 1px solid #e5e5ea; overflow-y: auto; }
.tabs { display: flex; gap: 4px; padding: 8px; border-bottom: 1px solid #e5e5ea; }
.tabs button { flex: 1; text-transform: capitalize; }
.tabs button.active { background: #e8f0fb; border-color: #0a66c2; }
.list { list-style: none; margin: 0; padding: 0; }
.list li { padding: 10px 14px; border-bottom: 1px solid #f0f0f2; cursor: pointer; }
.list li:hover { background: #f7f7f9; }
.list li.selected { background: #e8f0fb; }
.row { display: flex; justify-content: space-between; gap: 8px; }
.contact { font-weight: 600; }
.badge { padding: 0 6px; border-radius: 4px; background: #e5e5ea; }
.more { width: calc(100% - 16px); margin: 8px; }

.thread { display: flex; flex-direction: column; min-height: 0; }
.thread-head { display: flex; align-items: center; gap: 8px; padding: 12px 16px; background: #fff; border-bottom: 1px solid #e5e5ea; }
.messages { flex: 1; overflow-y: auto; padding: 16px; display: flex; flex-direction: column; gap: 8px; }
.bubble { max-width: 65%; padding: 8px 12px; border-radius: 12px; background: #fff; border: 1px solid #e5e5ea; }
.bubble.in { align-self: flex-start; }
.bubble.out { align-self: flex-end; background: #e8f0fb; border-color: #cfe0f5; }
.bubble.draft { opacity: 0.7; }
.meta { margin-top: 2px; font-size: 11px; color: #6e6e73; }
.status.delivered { color: #1b7f3b; }
.status.failed { color: #c62828; font-weight: 600; }
.composer { display: flex; gap: 8px; padding: 12px 16px; background: #fff; border-top: 1px solid #e5e5ea; }
.composer input { flex: 1; }

